custom_css:
/* ============================================================
   INVISIBLE CITIES — тема для Tavo по книге Итало Кальвино
   Ответы персонажа — рассказы Марко Поло на синем шёлке:
   каждый подписан одним из 55 городов и отражается внизу,
   как Вальдрада в озере. Ваши сообщения — реплики Хубилай-хана,
   чёрный лак и печать. Поле ввода — шахматная доска хана:
   пока Марко отвечает, по ней ходит конь.
   Шрифты Alegreya и Cinzel (SIL OFL 1.1) встроены в тему.
   Нужен Advanced Rendering.
   ============================================================ */

@font-face {
  font-family: "Alegreya";
  font-style: normal;
  font-weight: 400 800;
  font-display: swap;
  src: url("theme/assets/alegreya-normal-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Alegreya";
  font-style: normal;
  font-weight: 400 800;
  font-display: swap;
  src: url("theme/assets/alegreya-normal-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Alegreya";
  font-style: italic;
  font-weight: 400 800;
  font-display: swap;
  src: url("theme/assets/alegreya-italic-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Alegreya";
  font-style: italic;
  font-weight: 400 800;
  font-display: swap;
  src: url("theme/assets/alegreya-italic-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Cinzel";
  font-style: normal;
  font-weight: 400 900;
  font-display: swap;
  src: url("theme/assets/cinzel-latin.woff2") format("woff2");
}

/* 55 городов по кругу. Счётчик идёт по сообщениям на экране,
   поэтому при прокрутке названия меняются: города Кальвино
   никогда не бывают одними и теми же дважды. */
@counter-style invisible-cities {
  system: cyclic;
  symbols: "Diomira" "Isidora" "Dorothea" "Zaira" "Anastasia" "Tamara" "Zora" "Despina" "Zirma" "Isaura" "Maurilia" "Fedora" "Zoe" "Zenobia" "Euphemia" "Zobeide" "Hypatia" "Armilla" "Chloe" "Valdrada" "Olivia" "Sophronia" "Eutropia" "Zemrude" "Aglaura" "Octavia" "Ersilia" "Baucis" "Leandra" "Melania" "Esmeralda" "Phyllis" "Pyrrha" "Adelma" "Eudoxia" "Moriana" "Clarice" "Eusapia" "Beersheba" "Leonia" "Irene" "Argia" "Thekla" "Trude" "Olinda" "Laudomia" "Perinthia" "Procopia" "Raissa" "Andria" "Cecilia" "Marozia" "Penthesilea" "Theodora" "Berenice";
}

:root {
  counter-reset: city;
}

/* ---------- Анимации ---------- */

/* Ход конём по доске: квадраты 16px, буква «Г» за ход */
@keyframes cities-knight {
  0%    { background-position: 0 0, 0 0, 0 0, 0 0; }
  8.3%  { background-position: 32px 16px, 32px 16px, 0 0, 0 0; }
  16.6% { background-position: 64px 32px, 64px 32px, 0 0, 0 0; }
  25%   { background-position: 96px 16px, 96px 16px, 0 0, 0 0; }
  33.3% { background-position: 128px 0, 128px 0, 0 0, 0 0; }
  41.6% { background-position: 160px 16px, 160px 16px, 0 0, 0 0; }
  50%   { background-position: 192px 32px, 192px 32px, 0 0, 0 0; }
  58.3% { background-position: 224px 16px, 224px 16px, 0 0, 0 0; }
  66.6% { background-position: 256px 0, 256px 0, 0 0, 0 0; }
  75%   { background-position: 288px 16px, 288px 16px, 0 0, 0 0; }
  83.3% { background-position: 256px 32px, 256px 32px, 0 0, 0 0; }
  91.6% { background-position: 224px 16px, 224px 16px, 0 0, 0 0; }
  100%  { background-position: 0 0, 0 0, 0 0, 0 0; }
}

/* ---------- Типографика ---------- */
.tavo-bubble-content,
.tavo-composer-input {
  font-family: "Alegreya", "Noto Serif", Georgia, serif;
}

.tavo-message-content {
  line-height: 1.6;
}

.tavo-message-content::selection,
.tavo-message-content *::selection {
  background: rgba(212, 175, 106, 0.4);
  color: inherit;
}

/* ---------- Марко: рассказ на синем шёлке ---------- */
.tavo-bubble {
  border-radius: 3px;
}

.tavo-character-bubble {
  counter-increment: city;
  background-color: rgba(18, 26, 58, 0.9);
  background-image:
    url("theme/assets/corner-tl.svg"),
    url("theme/assets/corner-tr.svg"),
    url("theme/assets/corner-bl.svg"),
    url("theme/assets/corner-br.svg"),
    url("theme/assets/silk.png");
  background-size: 14px 14px, 14px 14px, 14px 14px, 14px 14px, 64px 64px;
  background-repeat: no-repeat, no-repeat, no-repeat, no-repeat, repeat;
  background-position: left 4px top 4px, right 4px top 4px, left 4px bottom 4px, right 4px bottom 4px, 0 0;
  border: 1px solid rgba(212, 175, 106, 0.28);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.45);
  padding: 12px 18px;
  /* Вальдрада: под каждым рассказом мерцает его отражение */
  -webkit-box-reflect: below 3px linear-gradient(to bottom, transparent calc(100% - 20px), rgba(0, 0, 0, 0.22));
}

/* Название города над каждым рассказом */
.tavo-character-bubble-content::before {
  content: counter(city, invisible-cities);
  display: block;
  margin-bottom: 4px;
  font-family: "Cinzel", Georgia, serif;
  font-size: 0.7em;
  font-weight: 600;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: #d4af6a;
  opacity: 0.85;
}

/* ---------- Хубилай-хан: чёрный лак и печать ---------- */
.tavo-user-bubble {
  background-color: rgba(12, 11, 16, 0.92);
  background-image: url("theme/assets/seal.svg");
  background-size: 16px 16px;
  background-repeat: no-repeat;
  background-position: right 7px top 7px;
  border-right: 2px solid #c8452c;
  padding-right: 28px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.45);
}

/* ---------- Имена и аватары ---------- */
.tavo-speaker-name {
  font-family: "Cinzel", Georgia, serif;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: #d4af6a;
  font-size: 0.85em;
}

.tavo-avatar {
  outline: 1.5px solid rgba(212, 175, 106, 0.8);
  outline-offset: -1.5px;
}

/* ---------- Блокнот Марко, разделитель, вложения ---------- */
.tavo-message-reasoning {
  font-style: italic;
  border-left: 1px solid rgba(79, 138, 122, 0.8);
  padding-left: 10px;
  color: #9fb3d1;
}

.tavo-message-reasoning > summary {
  color: #8fbfb0;
}

.tavo-message-divider {
  height: 28px;
  border: 0;
  background: url("theme/assets/divider.svg") center / min(320px, 76%) auto no-repeat;
}

.tavo-message-attachments {
  outline: 1px solid rgba(212, 175, 106, 0.6);
  outline-offset: 3px;
}

.tavo-action-bar-button,
.tavo-action-bar-button-group {
  background-color: rgba(12, 11, 16, 0.75);
  border-radius: 3px;
}

/* ---------- Поле ввода: шахматная доска хана ---------- */
.tavo-composer-shell {
  background-color: rgba(12, 11, 16, 0.94);
  background-image: conic-gradient(rgba(212, 175, 106, 0.07) 25%, transparent 0 50%, rgba(212, 175, 106, 0.07) 0 75%, transparent 0);
  background-size: 32px 32px;
  border: 1px solid rgba(212, 175, 106, 0.38);
  border-radius: 4px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.5);
}

/* Пока Марко отвечает, по доске ходит конь, подсвечивая клетки */
:root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
  background-image:
    url("theme/assets/knight.svg"),
    linear-gradient(rgba(212, 175, 106, 0.28), rgba(212, 175, 106, 0.28)),
    conic-gradient(rgba(212, 175, 106, 0.07) 25%, transparent 0 50%, rgba(212, 175, 106, 0.07) 0 75%, transparent 0),
    linear-gradient(transparent, transparent);
  background-size: 16px 16px, 16px 16px, 32px 32px, auto;
  background-repeat: no-repeat, no-repeat, repeat, no-repeat;
  animation: cities-knight 7.2s steps(1, end) infinite;
}

.tavo-composer-input {
  color: #e8dccb;
  caret-color: #d4af6a;
}

.tavo-composer-input::placeholder {
  color: #7d7a8c;
  font-style: italic;
}

.tavo-composer-send-icon,
.tavo-composer-add-icon,
.tavo-composer-voice-icon,
.tavo-composer-stop-icon {
  filter: sepia(1) saturate(1.5) brightness(0.95);
}

@media (prefers-reduced-motion: reduce) {
  :root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
    animation: none;
  }
}
